// Des: Read an owner-captured HAR or curl command into a request spec
// Flo: detect HAR (starts with brace) or curl > pull method, URL, headers, body > refuse TLS-bypass flags > fill {param} templates > hide secret query values for storage
// I/O: spec text + params k=v&k2=v2 (caller) > Spec; errors BadSpec PinBypass
// ===================================================================
const std = @import("std"); const mem = std.mem;
const CF = .{ .hdrz = 64, .skip = @as([]const []const u8, &.{ "host", "content-length", "connection", "accept-encoding", "transfer-encoding", "upgrade", "te", "keep-alive" }), .secr = @as([]const []const u8, &.{ "token", "sig", "signature", "key", "apikey", "api_key", "auth", "access_token", "hmac", "secret", "password", "sessionid" }) };
pub const Hdr = struct { name: []const u8, valu: []const u8 };
pub const Spec = struct { meth: []const u8 = "GET", urlz: []const u8 = "", hdrs: []const Hdr = &.{}, body: []const u8 = "" };
fn skipHdr(name: []const u8) bool { if (name.len == 0 or name[0] == ':') return true; for (CF.skip) |sk| if (std.ascii.eqlIgnoreCase(sk, name)) return true; return false; }
fn harRead(aren: std.mem.Allocator, text: []const u8) !Spec { const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, text, .{ .allocate = .alloc_always }) catch return error.BadSpec; if (valu != .object) return error.BadSpec; const logz = valu.object.get("log") orelse return error.BadSpec; if (logz != .object) return error.BadSpec; const ents = logz.object.get("entries") orelse return error.BadSpec; if (ents != .array or ents.array.items.len == 0) return error.BadSpec; const ent = ents.array.items[0]; if (ent != .object) return error.BadSpec; if (ent.object.get("_securityState")) |sst| { if (sst == .string and mem.eql(u8, sst.string, "insecure")) return error.PinBypass; } const req = ent.object.get("request") orelse return error.BadSpec; if (req != .object) return error.BadSpec; var spc: Spec = .{}; if (req.object.get("method")) |mth| { if (mth == .string) spc.meth = mth.string; } const urv = req.object.get("url") orelse return error.BadSpec; if (urv != .string) return error.BadSpec; spc.urlz = urv.string; var list: std.ArrayList(Hdr) = .empty; if (req.object.get("headers")) |hds| { if (hds == .array) { for (hds.array.items) |hd| { if (hd != .object or list.items.len >= CF.hdrz) continue; const nm = hd.object.get("name") orelse continue; const vl = hd.object.get("value") orelse continue; if (nm != .string or vl != .string or skipHdr(nm.string)) continue; try list.append(aren, .{ .name = nm.string, .valu = vl.string }); } } } spc.hdrs = try list.toOwnedSlice(aren); if (req.object.get("postData")) |pd| { if (pd == .object) { if (pd.object.get("text")) |tx| { if (tx == .string) spc.body = tx.string; } } } return spc; }
fn tokens(aren: std.mem.Allocator, text: []const u8) ![]const []const u8 { var outp: std.ArrayList([]const u8) = .empty; var cur: std.ArrayList(u8) = .empty; var inw = false; var idx: usize = 0; while (idx < text.len) { const chr = text[idx]; if (chr == '\\' and idx + 1 < text.len and (text[idx + 1] == '\n' or text[idx + 1] == '\r')) { idx += 2; if (idx < text.len and text[idx - 1] == '\r' and text[idx] == '\n') idx += 1; continue; } if (std.ascii.isWhitespace(chr)) { if (inw) { try outp.append(aren, try cur.toOwnedSlice(aren)); cur = .empty; inw = false; } idx += 1; continue; } inw = true; if (chr == '\'' or (chr == '$' and idx + 1 < text.len and text[idx + 1] == '\'')) { const ansi = chr == '$'; idx += if (ansi) 2 else 1; while (idx < text.len and text[idx] != '\'') { if (ansi and text[idx] == '\\' and idx + 1 < text.len) { idx += 1; switch (text[idx]) { 'n' => try cur.append(aren, '\n'), 'r' => try cur.append(aren, '\r'), 't' => try cur.append(aren, '\t'), else => try cur.append(aren, text[idx]) } idx += 1; continue; } try cur.append(aren, text[idx]); idx += 1; } idx += 1; continue; } if (chr == '"') { idx += 1; while (idx < text.len and text[idx] != '"') { if (text[idx] == '\\' and idx + 1 < text.len) { idx += 1; } try cur.append(aren, text[idx]); idx += 1; } idx += 1; continue; } if (chr == '\\' and idx + 1 < text.len) { idx += 1; } try cur.append(aren, text[idx]); idx += 1; } if (inw) try outp.append(aren, try cur.toOwnedSlice(aren)); return outp.toOwnedSlice(aren); }
fn curlRead(aren: std.mem.Allocator, text: []const u8) !Spec { const tk = try tokens(aren, text); if (tk.len < 2 or !mem.eql(u8, tk[0], "curl")) return error.BadSpec; var spc: Spec = .{}; var list: std.ArrayList(Hdr) = .empty; var mset = false; var idx: usize = 1; while (idx < tk.len) : (idx += 1) { const item = tk[idx]; if (mem.eql(u8, item, "-k") or mem.eql(u8, item, "--insecure") or mem.eql(u8, item, "--proxy-insecure") or mem.eql(u8, item, "--pinnedpubkey")) return error.PinBypass; const isv = mem.eql(u8, item, "-H") or mem.eql(u8, item, "--header") or mem.eql(u8, item, "-X") or mem.eql(u8, item, "--request") or mem.eql(u8, item, "-d") or mem.eql(u8, item, "--data") or mem.eql(u8, item, "--data-raw") or mem.eql(u8, item, "--data-binary") or mem.eql(u8, item, "-b") or mem.eql(u8, item, "--cookie") or mem.eql(u8, item, "-A") or mem.eql(u8, item, "--user-agent") or mem.eql(u8, item, "-u") or mem.eql(u8, item, "-x") or mem.eql(u8, item, "--proxy") or mem.eql(u8, item, "-e") or mem.eql(u8, item, "--referer"); if (isv) { idx += 1; if (idx >= tk.len) return error.BadSpec; const val = tk[idx]; if (mem.eql(u8, item, "-H") or mem.eql(u8, item, "--header")) { const col = mem.findScalar(u8, val, ':') orelse return error.BadSpec; const nm = mem.trim(u8, val[0..col], " \t"); if (!skipHdr(nm) and list.items.len < CF.hdrz) try list.append(aren, .{ .name = nm, .valu = mem.trim(u8, val[col + 1 ..], " \t") }); } else if (mem.eql(u8, item, "-X") or mem.eql(u8, item, "--request")) { spc.meth = val; mset = true; } else if (mem.eql(u8, item, "-b") or mem.eql(u8, item, "--cookie")) { try list.append(aren, .{ .name = "Cookie", .valu = val }); } else if (mem.eql(u8, item, "-A") or mem.eql(u8, item, "--user-agent")) { try list.append(aren, .{ .name = "User-Agent", .valu = val }); } else if (mem.eql(u8, item, "-e") or mem.eql(u8, item, "--referer")) { try list.append(aren, .{ .name = "Referer", .valu = val }); } else if (mem.startsWith(u8, item, "-d") or mem.startsWith(u8, item, "--data")) { spc.body = val; } continue; } if (item.len > 0 and item[0] == '-') continue; if (spc.urlz.len == 0) spc.urlz = item; } if (spc.urlz.len == 0) return error.BadSpec; if (spc.body.len > 0 and !mset) spc.meth = "POST"; spc.hdrs = try list.toOwnedSlice(aren); return spc; }
pub fn specRead(aren: std.mem.Allocator, text: []const u8) !Spec { const trm = mem.trim(u8, text, " \t\r\n\xEF\xBB\xBF"); if (trm.len == 0) return error.BadSpec; if (trm[0] == '{') return harRead(aren, trm); return curlRead(aren, trm); }
fn paramGet(parm: []const u8, name: []const u8) ?[]const u8 { var itr = mem.splitScalar(u8, parm, '&'); while (itr.next()) |pair| { const eqp = mem.findScalar(u8, pair, '=') orelse continue; if (mem.eql(u8, pair[0..eqp], name)) return pair[eqp + 1 ..]; } return null; }
pub fn fill(aren: std.mem.Allocator, text: []const u8, parm: []const u8) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var idx: usize = 0; while (idx < text.len) { if (text[idx] == '{') { var jdx = idx + 1; while (jdx < text.len and (std.ascii.isLower(text[jdx]) or std.ascii.isDigit(text[jdx]) or text[jdx] == '_')) jdx += 1; if (jdx > idx + 1 and jdx < text.len and text[jdx] == '}') { const val = paramGet(parm, text[idx + 1 .. jdx]) orelse return error.BadSpec; try outp.appendSlice(aren, val); idx = jdx + 1; continue; } } try outp.append(aren, text[idx]); idx += 1; } return outp.toOwnedSlice(aren); }
pub fn specFill(aren: std.mem.Allocator, spc: Spec, parm: []const u8) !Spec { var out = spc; out.urlz = try fill(aren, spc.urlz, parm); out.body = try fill(aren, spc.body, parm); const hd = try aren.alloc(Hdr, spc.hdrs.len); for (spc.hdrs, 0..) |item, ix| hd[ix] = .{ .name = item.name, .valu = try fill(aren, item.valu, parm) }; out.hdrs = hd; return out; }
pub fn urlSafe(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { const qix = mem.findScalar(u8, urlz, '?') orelse return urlz; var outp: std.ArrayList(u8) = .empty; try outp.appendSlice(aren, urlz[0..qix]); var first = true; var itr = mem.splitScalar(u8, urlz[qix + 1 ..], '&'); while (itr.next()) |pair| { const eqp = mem.findScalar(u8, pair, '=') orelse pair.len; var secr = false; for (CF.secr) |sk| { if (std.ascii.eqlIgnoreCase(sk, pair[0..eqp])) secr = true; } if (secr) continue; try outp.append(aren, if (first) '?' else '&'); first = false; try outp.appendSlice(aren, pair); } return outp.toOwnedSlice(aren); }
